import { NextRequest, NextResponse } from "next/server";
import { prisma } from "../../..//lib/db";
import { openai } from "../../..//lib/openai";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const TITLE_MAX = 200;
const CONTENT_MAX = 8000;

export async function GET() {
  try {
    const notes = await prisma.note.findMany({
      orderBy: { createdAt: "desc" },
      select: {
        id: true,
        title: true,
        content: true,
        summary: true,
        createdAt: true,
      },
    });
    return NextResponse.json({ notes });
  } catch (err) {
    console.error("GET /api/notes error:", err);
    return NextResponse.json({ error: "Failed to fetch notes" }, { status: 500 });
  }
}

export async function POST(req: NextRequest) {
  try {
    const contentType = req.headers.get("content-type") || "";
    if (!contentType.includes("application/json")) {
      return NextResponse.json({ error: "Invalid content type" }, { status: 400 });
    }

    const body = await req.json().catch(() => null);
    if (!body || typeof body !== "object") {
      return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
    }

    const title = typeof body.title === "string" ? body.title.trim() : "";
    const content = typeof body.content === "string" ? body.content.trim() : "";

    if (!title || !content) {
      return NextResponse.json({ error: "Title and content are required" }, { status: 400 });
    }
    if (title.length > TITLE_MAX) {
      return NextResponse.json({ error: `Title too long (max ${TITLE_MAX} chars)` }, { status: 400 });
    }
    if (content.length > CONTENT_MAX) {
      return NextResponse.json({ error: `Content too long (max ${CONTENT_MAX} chars)` }, { status: 400 });
    }

    // Generate a brief two-sentence summary
    const completion = await openai.chat.completions.create({
      model: "gpt-4o-mini",
      messages: [
        {
          role: "system",
          content:
            "You are a helpful assistant that writes concise, neutral summaries. Respond with exactly two sentences. Avoid emojis and quotes.",
        },
        {
          role: "user",
          content: `Create a concise, two-sentence summary of the following note. Keep it under ~60 words total.\n\nTitle: ${title}\n\nContent:\n${content}`,
        },
      ],
      temperature: 0.3,
      max_tokens: 120,
    });

    const summary =
      completion.choices?.[0]?.message?.content?.trim() ||
      "No summary available.";

    const note = await prisma.note.create({
      data: {
        title,
        content,
        summary,
      },
      select: {
        id: true,
        title: true,
        content: true,
        summary: true,
        createdAt: true,
      },
    });

    return NextResponse.json({ note }, { status: 201 });
  } catch (err: any) {
    console.error("POST /api/notes error:", err);
    const message =
      typeof err?.message === "string" ? err.message : "Failed to create note";
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

