        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ title, content }),
      });
      const data = await res.json();
      if (!res.ok) {
        throw new Error(data?.error || `Request failed (${res.status})`);
      }
      setTitle("");
      setContent("");
      setNotes((prev) => [data.note, ...prev]);
    } catch (e: any) {
      setSubmitError(e?.message || "Failed to create note");
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <main style={{ maxWidth: 720, margin: "2rem auto", padding: "0 1rem", fontFamily: "system-ui, sans-serif" }}>
      <h1 style={{ marginBottom: "1rem" }}>Notes</h1>

      <section
        style={{
          border: "1px solid #e5e7eb",
          borderRadius: 8,
          padding: "1rem",
          marginBottom: "2rem",
          background: "#fafafa",
        }}
      >
        <h2 style={{ marginTop: 0 }}>Create a note</h2>
        <form onSubmit={onSubmit} style={{ display: "grid", gap: "0.75rem" }}>
          <div>
            <label htmlFor="title" style={{ display: "block", fontWeight: 600, marginBottom: 4 }}>
              Title
            </label>
            <input
              id="title"
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="Enter a title"
              style={{
                width: "100%",
                padding: "0.5rem 0.75rem",
                border: "1px solid #d1d5db",
                borderRadius: 6,
              }}
            />
          </div>

          <div>
            <label htmlFor="content" style={{ display: "block", fontWeight: 600, marginBottom: 4 }}>
              Content
            </label>
            <textarea
              id="content"
              value={content}
              onChange={(e) => setContent(e.target.value)}
              placeholder="Write your note content..."
              rows={6}
              style={{
                width: "100%",
                padding: "0.5rem 0.75rem",
                border: "1px solid #d1d5db",
                borderRadius: 6,
                resize: "vertical",
              }}
            />
          </div>

          <div style={{ display: "flex", alignItems: "center", gap: "0.5rem" }}>
            <button
              type="submit"
              disabled={!canSubmit || submitting}
              style={{
                background: canSubmit && !submitting ? "#111827" : "#9ca3af",
                color: "white",
                border: 0,
                borderRadius: 6,
                padding: "0.5rem 0.9rem",
                cursor: canSubmit && !submitting ? "pointer" : "not-allowed",
              }}
            >
              {submitting ? "Creating..." : "Create note"}
            </button>
            {submitError && <span style={{ color: "#b91c1c" }}>{submitError}</span>}
          </div>
        </form>
      </section>

      <section>
        <h2 style={{ marginTop: 0, marginBottom: "0.5rem" }}>All notes</h2>
        {loadingList && <p>Loading notes...</p>}
        {errorList && <p style={{ color: "#b91c1c" }}>{errorList}</p>}
        {!loadingList && !errorList && notes.length === 0 && <p>No notes yet.</p>}

        <ul style={{ listStyle: "none", padding: 0, margin: 0, display: "grid", gap: "1rem" }}>
          {notes.map((n) => {
