import OpenAI from "openai";

export const openai = new OpenAI({
  apiKey: process.env.OPENAI_API_KEY, // If undefined, calls will throw
});

export async function summarizeNote({ title, content }: { title: string; content: string }) {
  if (!process.env.OPENAI_API_KEY) {
    // Dev-friendly fallback
    return "Summary unavailable (no OPENAI_API_KEY). The note discusses its title and content in brief.";
  }

  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 12_000); // 12s cap

  try {
    const res = await openai.responses.create({
      model: "gpt-4o-mini",
      temperature: 0.3,
      max_output_tokens: 120,
      input: [
        {
          role: "system",
          content:
            "You are a helpful assistant that writes concise, neutral summaries. Respond with exactly two sentences. Avoid emojis and quotes.",
        },
        {
          role: "user",
          content: `Create a concise, two-sentence summary of the following note. Keep it under ~60 words total.\n\nTitle: ${title}\n\nContent:\n${content}`,
        },
      ],
      signal: controller.signal,
    });

    const text = res.output_text?.trim();
    return text && text.length > 0 ? text : "No summary available.";
  } finally {
    clearTimeout(timeout);
  }
}

