+import OpenAI from "openai";
+
+if (!process.env.OPENAI_API_KEY) {
+  // Fail fast in production; allow local dev to notice quickly
+  if (process.env.NODE_ENV === "production") {
+    throw new Error("Missing OPENAI_API_KEY");
+  } else {
+    console.warn("Warning: OPENAI_API_KEY is not set.");
+  }
+}
+
+export const openai = new OpenAI({
+  apiKey: process.env.OPENAI_API_KEY,
+});
+
+export async function summarizeNote(content: string, maxChars = 400): Promise<string> {
+  const instruction = `Summarize the following note concisely. Return at most ${maxChars} characters. No preamble.`;
+  const res = await openai.chat.completions.create({
+    model: "gpt-4o-mini",
+    temperature: 0.2,
+    messages: [
+      { role: "system", content: "You are a concise note summarizer." },
+      { role: "user", content: `${instruction}\n\n---\n${content}\n---` },
+    ],
+  });
+  const text = res.choices[0]?.message?.content?.trim() ?? "";
+  return text.slice(0, maxChars);
+}

