+"use server";
+
+export const runtime = "nodejs";
+export const dynamic = "force-dynamic";
+
+import { prisma } from "@/prisma/client";
+import { revalidatePath } from "next/cache";
+import { getUserId } from "@/lib/auth";
+import { createNoteSchema, SUMMARY_MAX } from "@/lib/validation/note";
+import { summarizeNote } from "@/lib/openai";
+
+export async function createNote(prevState: any, formData: FormData) {
+  const userId = getUserId();
+  const data = {
+    title: String(formData.get("title") ?? ""),
+    content: String(formData.get("content") ?? ""),
+  };
+  const parsed = createNoteSchema.safeParse(data);
+  if (!parsed.success) {
+    return {
+      ok: false,
+      errors: parsed.error.flatten().fieldErrors,
+    };
+  }
+  const { title, content } = parsed.data;
+
+  let summary: string | null = null;
+  try {
+    summary = await summarizeNote(content, SUMMARY_MAX);
+  } catch (err) {
+    console.error("Summary generation failed:", err);
+    // Proceed without a summary
+  }
+
+  await prisma.note.create({
+    data: {
+      userId,
+      title,
+      content,
+      summary: summary ?? null,
+    },
+  });
+
+  revalidatePath("/notes");
+  return { ok: true };
+}
+
+export async function toggleArchive(noteId: string, archived: boolean) {
+  const userId = getUserId();
+  await prisma.note.updateMany({
+    where: { id: noteId, userId },
+    data: { archived },
+  });
+  revalidatePath("/notes");
+  return { ok: true };
+}
+
+export async function deleteNote(noteId: string) {
+  const userId = getUserId();
+  await prisma.note.deleteMany({
+    where: { id: noteId, userId },
+  });
+  revalidatePath("/notes");
+  return { ok: true };
+}

