import OpenAI from "openai"

const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY })

export async function summarizeNote(content: string) {
  const ctrl = new AbortController()
  const timeout = setTimeout(() => ctrl.abort(), 10_000) // 10s

  try {
    const prompt = `Summarize clearly in ≤400 characters:\n\n${content}`
    const res = await openai.chat.completions.create(
      {
        model: "gpt-4o-mini",
        messages: [{ role: "user", content: prompt }],
        temperature: 0.2,
        max_tokens: 180, // caps output for ≤400 chars
      },
      { signal: ctrl.signal }
    )
    return res.choices?.[0]?.message?.content?.trim() ?? ""
  } catch (err) {
    console.error("OpenAI summarize failed:", err)
    return ""
  } finally {
    clearTimeout(timeout)
  }
}

