"use server"

import { prisma } from "@/lib/prisma"
import { summarizeNote } from "@/lib/summarize"
import { getUserId } from "@/lib/auth"
import { revalidateTag } from "next/cache"
import { z } from "zod"

type State = { ok: boolean; error?: string }

const noteSchema = z.object({
  title: z.string().trim().min(1, "Title is required").max(100, "Max 100 chars"),
  content: z.string().trim().min(1, "Content is required").max(4000, "Max 4000 chars"),
})

export async function createNoteAction(prev: State, formData: FormData): Promise<State> {
  try {
    const userId = await getUserId()
    if (!userId) return { ok: false, error: "Unauthorized" }

    const parsed = noteSchema.safeParse({
      title: String(formData.get("title") ?? ""),
      content: String(formData.get("content") ?? ""),
    })
    if (!parsed.success) {
      const msg = parsed.error.issues[0]?.message ?? "Invalid input"
      return { ok: false, error: msg }
    }

    const { title, content } = parsed.data

    const note = await prisma.note.create({
      data: { userId, title, content, summary: "" },
      select: { id: true, content: true, userId: true },
    })

    ;(async () => {
      const summary = await summarizeNote(content)
      if (!summary) return
      try {
        await prisma.note.update({
          where: { id: note.id },
          data: { summary: summary.slice(0, 400) },
        })
        // If you’re using cache tags for lists:
        // revalidateTag(`notes:${userId}`)
      } catch (e) {
        console.error("Failed to save summary:", e)
      }
    })()

    // If you cache the list by tag, you could revalidate immediately for the new item:
    // revalidateTag(`notes:${userId}`)

    return { ok: true }
  } catch (e) {
    console.error("createNoteAction failed:", e)
    return { ok: false, error: "Something went wrong. Please try again." }
  }
}

