        temperature: 0.2,
        max_tokens: 180,
      },
      { signal: ctrl.signal }
    )
    const out = res.choices?.[0]?.message?.content?.trim() ?? ""
    return out.slice(0, 400)
  } catch (err) {
    console.error("OpenAI summarize failed (primary):", err)
    try {
      // small, cheap fallback
      const res2 = await openai.chat.completions.create(
        {
