  import OpenAI from "openai"
  const client = new OpenAI()

  export async function summarizeNote(content: string) {
    const ctrl = new AbortController()
    const t = setTimeout(() => ctrl.abort(), 10_000)
    try {
      const cleaned = String(content || "").replace(/\s+/g, " ").slice(0, 4000)
      if (!cleaned) return ""
      const res = await client.responses.create(
        {
          model: "gpt-4o-mini",
          temperature: 0.2,
          max_output_tokens: 180,
          input: [{ role: "user", content: `Summarize clearly in ≤400 characters. No preface:\n\n${cleaned}` }],
        },
        { signal: ctrl.signal }
      )
      const out = (res.output_text || "").trim()
      return out.slice(0, 400)
    } catch (e) {
      console.error("OpenAI summarize failed:", e)
      return ""
    } finally {
      clearTimeout(t)
    }
  }

