"use server";

import { revalidateTag } from "next/cache";
import { GenerateSummaryInputSchema } from "@/lib/validation";
import { getNoteById, updateNoteSummary } from "@/lib/db";
import { notesTagForUser } from "@/lib/cacheTags";

// Replace with your auth integration
function requireUserId() {
  return "demo-user-1";
}

export type GenerateSummaryState = {
  fieldErrors?: Partial<Record<"noteId", string>>;
  formError?: string;
  ok?: boolean;
};

async function callOpenAISummary({ title, content }: { title: string; content: string }): Promise<string> {
  const apiKey = process.env.OPENAI_API_KEY;
  if (!apiKey) throw new Error("OPENAI_API_KEY is not set");

  const prompt = [
    "You are a concise note summarizer.",
    "Return a single 1–2 sentence summary suitable for a subtitle UI.",
    "Avoid repeating the title; highlight the main point.",
    "",
    `Title: ${title}`,
    `Content:\n${content}`,
  ].join("\n");

  const resp = await fetch("https://api.openai.com/v1/chat/completions", {
    method: "POST",
    headers: {
      "Authorization": `Bearer ${apiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      model: "gpt-4o-mini",
      messages: [{ role: "user", content: prompt }],
      temperature: 0.3,
      max_tokens: 120,
    }),
    // Optional: tune for server actions
    // Next.js will stream/abort correctly; you can add a timeout wrapper if desired.
  });

  if (!resp.ok) {
    const text = await resp.text().catch(() => "");
    throw new Error(`OpenAI error: ${resp.status} ${text}`);
  }

  const data = await resp.json();
  const text = data?.choices?.[0]?.message?.content?.trim?.();
  if (!text) throw new Error("Empty summary from model");
  return text;
}

export async function generateSummaryAction(prev: GenerateSummaryState, formData: FormData): Promise<GenerateSummaryState> {
  const userId = requireUserId();

  const raw = { noteId: String(formData.get("noteId") ?? "") };
  const parsed = GenerateSummaryInputSchema.safeParse(raw);
  if (!parsed.success) {
    const zerr = parsed.error.flatten();
    return { fieldErrors: { noteId: zerr.fieldErrors.noteId?.[0] } };
  }

  const note = await getNoteById(parsed.data.noteId);
  if (!note || note.userId !== userId) {
    return { formError: "Note not found" };
  }

  try {
    const summary = await callOpenAISummary({ title: note.title, content: note.content });
    await updateNoteSummary(note.id, userId, summary);
    revalidateTag(notesTagForUser(userId));
    return { ok: true };
  } catch (e) {
    return { formError: e instanceof Error ? e.message : "Failed to generate summary. Please try again." };
  }
}

