"use server";

import { revalidateTag } from "next/cache";
import { GenerateSummaryInputSchema } from "@/lib/validation";
import { getNoteById, updateNoteSummary } from "@/lib/db";
import { notesTagForUser } from "@/lib/cacheTags";
import { getOpenAI } from "@/lib/openai";
import { summaryRatelimit } from "@/lib/rateLimit";

// Replace with your auth integration
function requireUserId() {
  return "demo-user-1";
}

export type GenerateSummaryState = {
  fieldErrors?: Partial<Record<"noteId", string>>;
  formError?: string;
  ok?: boolean;
};

type SummaryArgs = { title: string; content: string };

async function callOpenAISummary({ title, content }: SummaryArgs): Promise<string> {
  const client = getOpenAI();

  // Prompt
  const userPrompt = [
    "You are a concise note summarizer.",
    "Return a single 1–2 sentence summary suitable for a subtitle UI.",
    "Avoid repeating the title; highlight the main point.",
    "",
    `Title: ${title}`,
    `Content:\n${content}`,
  ].join("\n");

  // Abort/timeout
  const ac = new AbortController();
  const timeout = setTimeout(() => ac.abort(), 12_000); // 12s server action timeout

  // Simple retry with exponential backoff on transient errors
  const attempts = 3;
  let lastErr: unknown;

  for (let i = 0; i < attempts; i++) {
    try {
      const resp = await client.chat.completions.create(
        {
          model: "gpt-4o-mini",
          messages: [{ role: "user", content: userPrompt }],
          temperature: 0.3,
          max_tokens: 120,
        },
        { signal: ac.signal }
      );

      clearTimeout(timeout);

      const text = resp.choices?.[0]?.message?.content?.trim();
      if (!text) throw new Error("Empty summary from model");

      // Light cleanup: strip quotes and clamp length
      const cleaned = text.replace(/^["'\s]+|["'\s]+$/g, "");
      return cleaned.length > 600 ? cleaned.slice(0, 600) + "…" : cleaned;
    } catch (e: any) {
      lastErr = e;
      const isAbort = e?.name === "AbortError";
      const isRate = e?.status === 429;
      const is5xx = typeof e?.status === "number" && e.status >= 500;
      const isRetryable = isAbort || isRate || is5xx;

      if (i < attempts - 1 && isRetryable) {
        const backoff = 300 * Math.pow(2, i); // 300ms, 600ms
        await new Promise(r => setTimeout(r, backoff));
        continue;
      }

      if (isAbort) throw new Error("OpenAI request timed out");
      throw e instanceof Error ? e : new Error("OpenAI request failed");
    }
  }

  throw lastErr instanceof Error ? lastErr : new Error("OpenAI request failed");
}

export async function generateSummaryAction(prev: GenerateSummaryState, formData: FormData): Promise<GenerateSummaryState> {
  const userId = requireUserId();

  const raw = { noteId: String(formData.get("noteId") ?? "") };
  const parsed = GenerateSummaryInputSchema.safeParse(raw);
  if (!parsed.success) {
    const zerr = parsed.error.flatten();
    return { fieldErrors: { noteId: zerr.fieldErrors.noteId?.[0] } };
  }

  const note = await getNoteById(parsed.data.noteId);
  if (!note || note.userId !== userId) {
    return { formError: "Note not found" };
  }

  // Optional: rate limit per user
  if (summaryRatelimit) {
    const { success, reset } = await summaryRatelimit.limit(`summary:${userId}`);
    if (!success) {
      const secs = Math.max(0, Math.ceil((reset - Date.now()) / 1000));
      return { formError: `Rate limit exceeded. Try again in ${secs}s.` };
    }
  }

  try {
    // Guard against empty content/title to avoid wasting tokens
    const title = note.title?.trim() ?? "";
    const content = note.content?.trim() ?? "";
    if (!title && !content) {
      await updateNoteSummary(note.id, userId, null);
      return { formError: "Cannot summarize an empty note." };
    }

    const summary = await callOpenAISummary({ title, content });
    await updateNoteSummary(note.id, userId, summary);
    revalidateTag(notesTagForUser(userId));
    return { ok: true };
  } catch (e) {
    return { formError: e instanceof Error ? e.message : "Failed to generate summary. Please try again." };
  }
}

