// Helper: normalize reset to seconds (works for seconds or epoch ms)
export function resetToSeconds(reset: number): number {
  // Heuristic: epoch ms is > 1e12, epoch sec is < 1e11 for the foreseeable future
  const isMs = reset > 1e12;
  const nowMs = Date.now();
  const targetMs = isMs ? reset : reset * 1000;
  const secs = Math.max(0, Math.ceil((targetMs - nowMs) / 1000));
