import type { Redis as UpstashRedis } from '@upstash/redis';
import type { Redis as IORedis } from 'ioredis';

type RateLimitDriver =
  | { kind: 'upstash'; client: UpstashRedis }
  | { kind: 'ioredis'; client: IORedis }
  | { kind: 'memory'; client: Map<string, { count: number; expiresAt: number }> };

let driverPromise: Promise<RateLimitDriver> | null = null;

async function getDriver(): Promise<RateLimitDriver> {
  if (driverPromise) return driverPromise;

  driverPromise = (async () => {
    const hasUpstash = !!process.env.UPSTASH_REDIS_REST_URL && !!process.env.UPSTASH_REDIS_REST_TOKEN;

    if (hasUpstash) {
      const { Redis } = await import('@upstash/redis');
      const client = new Redis({
        url: process.env.UPSTASH_REDIS_REST_URL!,
        token: process.env.UPSTASH_REDIS_REST_TOKEN!,
      });
      return { kind: 'upstash', client };
    }

    const isNode = typeof process !== 'undefined' && process.versions?.node;
    const hasIORedisUrl = !!process.env.REDIS_URL;

    if (isNode && hasIORedisUrl) {
      const mod = await import('ioredis');
      const client = new mod.default(process.env.REDIS_URL!, {
        // safe defaults for serverless
        maxRetriesPerRequest: 3,
        enableOfflineQueue: false,
        lazyConnect: true,
      });
      // Connect lazily, swallow errors until first use
      try {
        await client.connect();
      } catch {
        // fall back to memory
        await client.quit().catch(() => {});
        return { kind: 'memory', client: new Map() };
      }
      return { kind: 'ioredis', client };
    }

    return { kind: 'memory', client: new Map() };
  })();

  return driverPromise;
}

export type RateLimitResult = {
  allowed: boolean;
  remaining: number;
  limit: number;
  reset: number; // epoch ms when window resets (normalized boundary)
  retryAfter: number; // seconds until reset, ceil
};

export function resetToSeconds(resetEpochMs: number): number {
  const now = Date.now();
  const diffMs = Math.max(0, resetEpochMs - now);
  return Math.ceil(diffMs / 1000);
}

function windowResetBoundary(nowMs: number, windowSeconds: number): number {
  const wMs = windowSeconds * 1000;
  const start = Math.floor(nowMs / wMs) * wMs;
  return start + wMs; // next boundary
}

async function rateLimitUpstash(
  client: UpstashRedis,
  key: string,
  limit: number,
  windowSeconds: number
): Promise<RateLimitResult> {
  const now = Date.now();
  const reset = windowResetBoundary(now, windowSeconds);
  const ttlSec = Math.ceil((reset - now) / 1000);

  // Use a single key per window boundary: rl:{key}:{boundaryTimestamp}
  const bucketKey = `rl:${key}:${Math.floor(reset / 1000)}`;
  // INCR and set expiry in a pipeline
  const res = await client.multi()
    .incr(bucketKey)
    .expire(bucketKey, ttlSec)
    .exec<[number, number]>();

  const current = res?.[0] ?? 0;
  const allowed = current <= limit;
  const remaining = Math.max(0, limit - current);

  return {
    allowed,
    remaining,
    limit,
    reset,
    retryAfter: resetToSeconds(reset),
  };
}

async function rateLimitIORedis(
  client: IORedis,
  key: string,
  limit: number,
  windowSeconds: number
): Promise<RateLimitResult> {
  const now = Date.now();
  const reset = windowResetBoundary(now, windowSeconds);
  const ttlSec = Math.ceil((reset - now) / 1000);
  const bucketKey = `rl:${key}:${Math.floor(reset / 1000)}`;

  const pipeline = client.multi();
  pipeline.incr(bucketKey);
  pipeline.expire(bucketKey, ttlSec);
  const [[, currentRaw]] = (await pipeline.exec()) as any;
  const current = Number(currentRaw) || 0;

  return {
    allowed: current <= limit,
    remaining: Math.max(0, limit - current),
    limit,
    reset,
    retryAfter: resetToSeconds(reset),
  };
}

async function rateLimitMemory(
  store: Map<string, { count: number; expiresAt: number }>,
  key: string,
  limit: number,
  windowSeconds: number
): Promise<RateLimitResult> {
  const now = Date.now();
  const reset = windowResetBoundary(now, windowSeconds);
  const bucketKey = `rl:${key}:${Math.floor(reset / 1000)}`;

  const existing = store.get(bucketKey);
  if (!existing) {
    store.set(bucketKey, { count: 1, expiresAt: reset });
    // best-effort cleanup
    setTimeout(() => store.delete(bucketKey), reset - now + 1000).unref?.();
    return { allowed: true, remaining: limit - 1, limit, reset, retryAfter: resetToSeconds(reset) };
  } else {
    existing.count += 1;
    const allowed = existing.count <= limit;
    return {
      allowed,
      remaining: Math.max(0, limit - existing.count),
      limit,
      reset: existing.expiresAt,
      retryAfter: resetToSeconds(existing.expiresAt),
    };
  }
}

export async function rateLimit(
  key: string,
  opts: { limit: number; windowSeconds: number }
): Promise<RateLimitResult> {
  const driver = await getDriver();
  if (driver.kind === 'upstash') {
    return rateLimitUpstash(driver.client, key, opts.limit, opts.windowSeconds);
  }
  if (driver.kind === 'ioredis') {
    return rateLimitIORedis(driver.client, key, opts.limit, opts.windowSeconds);
  }
  return rateLimitMemory(driver.client, key, opts.limit, opts.windowSeconds);
}
