- Simple interface to plug model and system prompt

File: lib/summary.ts
```
import OpenAI from 'openai';

export type SummaryOptions = {
  model?: string;
  maxInputBytes?: number; // clamp input by bytes
  retries?: number;
  baseDelayMs?: number; // exponential backoff base
  attemptTimeoutMs?: number; // per attempt
  systemPrompt?: string;
};

function clampUtf8Bytes(text: string, maxBytes: number): string {
  const enc = new TextEncoder();
  const bytes = enc.encode(text);
  if (bytes.byteLength <= maxBytes) return text;
  // Truncate by bytes safely
  let end = Math.min(bytes.byteLength, maxBytes);
  // walk back until valid UTF-8 boundary (continuation bytes start with 10xxxxxx)
  while (end > 0 && (bytes[end] & 0b11000000) === 0b10000000) end--;
  const sliced = bytes.slice(0, end);
  return new TextDecoder('utf-8', { fatal: false }).decode(sliced);
}

function sleep(ms: number) {
  return new Promise((res) => setTimeout(res, ms));
}

export type SummaryResponse = {
  summary: string;
  usage?: { inputTokens?: number; outputTokens?: number };
};

export async function callOpenAISummary(
  input: string,
  options?: SummaryOptions
): Promise<SummaryResponse> {
  const {
    model = 'gpt-4o-mini',
    maxInputBytes = 16_000,
    retries = 3,
    baseDelayMs = 250,
    attemptTimeoutMs = 12_000,
    systemPrompt = 'You are a helpful assistant that summarizes text succinctly and faithfully.',
  } = options ?? {};

  const client = new OpenAI({
    apiKey: process.env.OPENAI_API_KEY,
  });

  if (!process.env.OPENAI_API_KEY) {
    throw new Error('Missing OPENAI_API_KEY');
  }

  const clamped = clampUtf8Bytes(input, maxInputBytes);

  let lastErr: any;
  for (let attempt = 0; attempt < retries; attempt++) {
    const ac = new AbortController();
    const timeout = setTimeout(() => ac.abort(), attemptTimeoutMs);

    try {
      const res = await client.chat.completions.create(
        {
          model,
          messages: [
            { role: 'system', content: systemPrompt },
            { role: 'user', content: `Summarize the following:\n\n${clamped}` },
          ],
          temperature: 0.2,
          max_tokens: 320,
        },
        { signal: ac.signal }
      );

      clearTimeout(timeout);

      const msg = res.choices?.[0]?.message?.content ?? '';
      const usage = res.usage
        ? { inputTokens: res.usage.prompt_tokens, outputTokens: res.usage.completion_tokens }
        : undefined;

      if (!msg) throw new Error('Empty summary from model');
      return { summary: msg, usage };
    } catch (err: any) {
      clearTimeout(timeout);
      lastErr = err;

      const status = err?.status ?? err?.response?.status;
      const isRetryable =
        err?.name === 'AbortError' ||
        status === 429 ||
        (status >= 500 && status < 600) ||
        // network-ish
        err?.code === 'ETIMEDOUT' ||
        err?.code === 'ECONNRESET';

      if (attempt < retries - 1 && isRetryable) {
        const delay = baseDelayMs * Math.pow(2, attempt);
        await sleep(delay);
        continue;
      }
      break;
    }
  }

  throw lastErr ?? new Error('OpenAI summary failed');
}
