import 'server-only';
import { NextRequest, NextResponse } from 'next/server';
import { rateLimit, resetToSeconds } from '@/lib/rateLimit';
import { callOpenAISummary } from '@/lib/summary';
import { summaryKeyHash } from '@/lib/hash';

export const runtime = 'nodejs';

type Body = {
  text: string;
  prevHash?: string | null; // optional previous content hash from client or DB
  // future: userId for per-user RL; for now per-IP
};

export async function POST(req: NextRequest) {
  try {
    const ip =
      req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ||
      req.ip ||
      'anonymous';

    const { text, prevHash }: Body = await req.json();

    if (!text || typeof text !== 'string') {
      return NextResponse.json({ error: 'Missing text' }, { status: 400 });
    }

    // Rate limit
    const rl = await rateLimit(`summarize:${ip}`, { limit: 10, windowSeconds: 60 });
    if (!rl.allowed) {
      return NextResponse.json(
        { error: 'Rate limit exceeded', retryAfter: rl.retryAfter, reset: rl.reset },
        {
          status: 429,
          headers: {
            'Retry-After': String(rl.retryAfter),
            'X-RateLimit-Limit': String(rl.limit),
            'X-RateLimit-Remaining': String(rl.remaining),
            'X-RateLimit-Reset': String(Math.floor(rl.reset / 1000)),
          },
        }
      );
    }

    // Optional content hashing: if unchanged, skip model call.
    const currentHash = summaryKeyHash(text, { normalize: true });

    if (prevHash && prevHash === currentHash) {
      // In a real app, you would fetch and return the stored summary by hash.
      // For now, we return a no-op response signaling unchanged content.
      return NextResponse.json({
        unchanged: true,
        hash: currentHash,
        // summary: '<fetch from DB by hash here>',
        rateLimit: {
          remaining: rl.remaining,
          resetSeconds: resetToSeconds(rl.reset),
        },
      });
    }

    // Call OpenAI safely
    const { summary, usage } = await callOpenAISummary(text, {
      model: process.env.OPENAI_SUMMARY_MODEL || 'gpt-4o-mini',
      maxInputBytes: 16_000,
      retries: 3,
      baseDelayMs: 250,
      attemptTimeoutMs: 12_000,
      systemPrompt:
        process.env.OPENAI_SUMMARY_SYSTEM_PROMPT ||
        'You are a helpful assistant that summarizes text succinctly and faithfully.',
    });

    // TODO: persist { hash: currentHash, summary } in your DB if desired
    // await db.summary.upsert({ where: { content_hash: currentHash }, create: { content_hash: currentHash, summary }, update: { summary } });

    return NextResponse.json({
      summary,
      hash: currentHash,
      usage,
      rateLimit: {
        remaining: rl.remaining,
        resetSeconds: resetToSeconds(rl.reset),
      },
    });
  } catch (err: any) {
    const msg = err?.message || 'Internal error';
    const status = err?.status || 500;
    return NextResponse.json({ error: msg }, { status });
  }
}
