'use client';

import { useState } from 'react';

export function SummaryForm() {
  const [text, setText] = useState('');
  const [prevHash, setPrevHash] = useState<string | null>(null);
  const [summary, setSummary] = useState<string | null>(null);
  const [wait, setWait] = useState<number | null>(null);
  const [loading, setLoading] = useState(false);

  async function onSubmit(e: React.FormEvent) {
    e.preventDefault();
    setLoading(true);
    setWait(null);
    setSummary(null);

    const res = await fetch('/api/summarize', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ text, prevHash }),
    });

    setLoading(false);

    if (res.status === 429) {
      const data = await res.json();
      setWait(data?.retryAfter ?? null);
      return;
    }

    const data = await res.json();

    if (data?.unchanged) {
      // No change; keep existing summary (you could show a toast)
      setWait(data?.rateLimit?.resetSeconds ?? null);
      return;
    }

    if (data?.summary) {
      setSummary(data.summary);
      setPrevHash(data.hash ?? null);
      setWait(data?.rateLimit?.resetSeconds ?? null);
    } else if (data?.error) {
      alert(data.error);
    }
  }

  return (
    <form onSubmit={onSubmit} style={{ display: 'grid', gap: 8 }}>
      <textarea value={text} onChange={(e) => setText(e.target.value)} rows={8} />
      <button type="submit" disabled={loading}>{loading ? 'Summarizing…' : 'Summarize'}</button>
      {wait != null && <small>Window resets in ~{wait}s</small>}
      {summary && (
        <div>
          <h4>Summary</h4>
          <pre>{summary}</pre>
        </div>
      )}
    </form>
  );
}
