lib/redis.ts
- Upstash REST if available; otherwise ioredis (lazy connect); else in-memory.

type CacheDriver =
  | { kind: 'upstash'; client: import('@upstash/redis').Redis }
  | { kind: 'ioredis'; client: import('ioredis').Redis }
  | { kind: 'memory'; client: Map<string, { value: string; exp: number | null }> };

let driverPromise: Promise<CacheDriver> | null = null;

export async function getCacheDriver(): Promise<CacheDriver> {
  if (driverPromise) return driverPromise;

  driverPromise = (async () => {
    const upstashUrl = process.env.UPSTASH_REDIS_REST_URL;
    const upstashToken = process.env.UPSTASH_REDIS_REST_TOKEN;

    if (upstashUrl && upstashToken) {
      const { Redis } = await import('@upstash/redis');
      const client = new Redis({ url: upstashUrl, token: upstashToken });
      return { kind: 'upstash', client };
    }

    const redisUrl = process.env.REDIS_URL;
    if (redisUrl) {
      const IORedis = (await import('ioredis')).default;
      const client = new IORedis(redisUrl, {
        lazyConnect: true,
        maxRetriesPerRequest: 2,
        enableReadyCheck: false,
      });
      return { kind: 'ioredis', client };
    }

    return { kind: 'memory', client: new Map() };
  })();

  return driverPromise;
}

export async function cacheGet(key: string): Promise<string | null> {
  const r = await getCacheDriver();
  if (r.kind === 'upstash') {
    return (await r.client.get<string>(key)) ?? null;
  }
  if (r.kind === 'ioredis') {
    return (await r.client.get(key)) ?? null;
  }
  // memory
  const entry = r.client.get(key);
  if (!entry) return null;
  if (entry.exp && Date.now() > entry.exp) {
    r.client.delete(key);
    return null;
  }
  return entry.value;
}

export async function cacheSet(key: string, value: string, ttlSeconds?: number): Promise<void> {
  const r = await getCacheDriver();
  if (r.kind === 'upstash') {
    if (ttlSeconds) await r.client.set(key, value, { ex: ttlSeconds });
    else await r.client.set(key, value);
    return;
  }
  if (r.kind === 'ioredis') {
    if (ttlSeconds) await r.client.set(key, value, 'EX', ttlSeconds);
    else await r.client.set(key, value);
    return;
  }
  // memory
  const exp = ttlSeconds ? Date.now() + ttlSeconds * 1000 : null;
  r.client.set(key, { value, exp });
}

