import { NextResponse } from 'next/server';
import { normalizeForHash, hashText } from '@/lib/hash';
import { cacheGet, cacheSet } from '@/lib/redis';
import { rateLimit } from '@/lib/rate-limit';
import { summarizeWithOpenAI } from '@/lib/openai'; // your existing OpenAI call

export const dynamic = 'force-dynamic';

const MAX_BYTES = 1_000_000; // 1MB
const CACHE_TTL_SECONDS = 60 * 60 * 24 * 7; // 7 days

export async function POST(req: Request) {
  // Optional: cap request size
  const len = req.headers.get('content-length');
  if (len && Number(len) > MAX_BYTES) {
    return NextResponse.json(
      { error: 'Request too large' },
      { status: 413, headers: { 'Content-Length': '0' } }
    );
  }

  // Rate limit
  const rl = await rateLimit(req); // expected to return { ok, limit, remaining, reset, retryAfter? }
  if (!rl.ok) {
    return NextResponse.json(
      { error: 'Rate limit exceeded', rateLimit: { limit: rl.limit, remaining: 0, reset: rl.reset } },
      {
        status: 429,
        headers: {
          'Retry-After': String(rl.retryAfter ?? Math.max(0, Math.floor((rl.reset - Date.now()) / 1000))),
          'X-RateLimit-Limit': String(rl.limit),
          'X-RateLimit-Remaining': '0',
          'X-RateLimit-Reset': String(Math.floor(rl.reset / 1000)),
        },
      }
    );
  }

  let body: { text?: string };
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 });
  }

  const raw = typeof body.text === 'string' ? body.text : '';
  if (!raw) {
    return NextResponse.json({ error: 'Missing "text"' }, { status: 400 });
  }

  const normalized = normalizeForHash(raw);
  const contentHash = hashText(normalized);
  const cacheKey = `sum:${contentHash}`;

  // Check cache
  const cached = await cacheGet(cacheKey);
  if (cached) {
    const res = NextResponse.json(
      {
        summary: cached,
        cached: true,
        hash: contentHash,
        rateLimit: { limit: rl.limit, remaining: rl.remaining, reset: rl.reset },
      },
      {
        headers: {
          'X-RateLimit-Limit': String(rl.limit),
          'X-RateLimit-Remaining': String(rl.remaining),
          'X-RateLimit-Reset': String(Math.floor(rl.reset / 1000)),
        },
      }
    );
    return res;
  }

  // Generate via OpenAI
  const summary = await summarizeWithOpenAI(normalized);

  // Cache result
  await cacheSet(cacheKey, summary, CACHE_TTL_SECONDS);

  // Success with headers
  return NextResponse.json(
    {
      summary,
      cached: false,
      hash: contentHash,
      rateLimit: { limit: rl.limit, remaining: rl.remaining, reset: rl.reset },
    },
    {
      headers: {
        'X-RateLimit-Limit': String(rl.limit),
        'X-RateLimit-Remaining': String(rl.remaining),
        'X-RateLimit-Reset': String(Math.floor(rl.reset / 1000)),
      },
    }
  );
}

Notes
- No explicit await connect/quit for Redis; first command triggers connection.
- If neither Upstash nor REDIS_URL is set, it falls back to an in-memory Map (fine for local/dev).
- TTL is 7 days as requested.
- Headers on success mirror current limiter state for client observability.
- You can optionally surface Retry-After on success too (pointing to reset), but usually not necessary.

